// Normaliza a saida do Entra e deixa visivel qualquer erro da API,
// em vez de devolver uma lista vazia que a interface leria como "nenhum usuario".
const term = $('Prepare Search Term').first().json.searchTerm || '';
const people = [];
let error = '';

for (const item of $input.all()) {
  const user = item.json || {};

  if (user.error) {
    const detail = user.error;
    error = typeof detail === 'string' ? detail : (detail.message || JSON.stringify(detail));
    continue;
  }
  if (!user.displayName && !user.mail && !user.userPrincipalName) continue;

  people.push({
    id: user.id || '',
    displayName: user.displayName || '',
    mail: user.mail || user.userPrincipalName || '',
    department: user.department || '',
    jobTitle: user.jobTitle || '',
  });
}

return [{ json: { ok: !error, term, count: people.length, people, error } }];

// Sanitiza e valida o CNPJ antes de gastar uma chamada na API.
// Aceita o formato numerico e o CNPJ alfanumerico (12 caracteres + 2 digitos verificadores),
// em que o valor de cada caractere e o codigo ASCII menos 48.
const input = $input.first().json || {};
const query = input.query || {};
const body = input.body || {};
const cnpj = String(query.cnpj || query.q || body.cnpj || body.q || '')
  .toUpperCase()
  .replace(/[^A-Z0-9]/g, '');

function isValid(value) {
  if (value.length !== 14) return false;
  if (/^(.)\1{13}$/.test(value)) return false;
  if (!/^[A-Z0-9]{12}[0-9]{2}$/.test(value)) return false;

  const valueOf = (char) => char.charCodeAt(0) - 48;
  const checkDigit = (base) => {
    let weight = base.length - 7;
    let sum = 0;
    for (let i = 0; i < base.length; i++) {
      sum += valueOf(base[i]) * weight--;
      if (weight < 2) weight = 9;
    }
    const rest = sum % 11;
    return rest < 2 ? 0 : 11 - rest;
  };

  return checkDigit(value.slice(0, 12)) === Number(value[12])
    && checkDigit(value.slice(0, 13)) === Number(value[13]);
}

const formatted = cnpj.length === 14
  ? `${cnpj.slice(0, 2)}.${cnpj.slice(2, 5)}.${cnpj.slice(5, 8)}/${cnpj.slice(8, 12)}-${cnpj.slice(12)}`
  : cnpj;
const valid = isValid(cnpj);

return [{
  json: {
    cnpj,
    cnpjFormatted: formatted,
    valid,
    ok: valid,
    error: valid ? '' : (cnpj ? 'CNPJ invalido: ' + formatted : 'Informe o CNPJ.'),
    company: null,
  },
}];

// Normaliza a resposta da API publica e deixa o erro visivel para a interface.
// Entende o formato da BrasilAPI e o da ReceitaWS, entao trocar de provedor nao quebra o form.
const prepared = $('Prepare CNPJ').first().json;
const raw = $input.first().json || {};
let error = '';

if (raw.error) {
  error = typeof raw.error === 'string' ? raw.error : (raw.error.message || JSON.stringify(raw.error));
} else if (!raw.cnpj && !raw.razao_social && !raw.nome) {
  error = raw.message || raw.detalhes || raw.type || 'CNPJ nao encontrado.';
}

const first = (...values) => values.find((v) => v !== undefined && v !== null && v !== '') || '';
const atividade = Array.isArray(raw.atividade_principal) ? (raw.atividade_principal[0] || {}) : {};

const company = error ? null : {
  cnpj: prepared.cnpj,
  cnpjFormatted: prepared.cnpjFormatted,
  razaoSocial: first(raw.razao_social, raw.nome),
  nomeFantasia: first(raw.nome_fantasia, raw.fantasia),
  situacao: first(raw.descricao_situacao_cadastral, raw.situacao),
  dataAbertura: first(raw.data_inicio_atividade, raw.abertura),
  atividadePrincipal: first(raw.cnae_fiscal_descricao, atividade.text),
  porte: first(raw.descricao_porte, raw.porte),
  logradouro: first(raw.logradouro),
  numero: first(raw.numero),
  bairro: first(raw.bairro),
  municipio: first(raw.municipio),
  uf: first(raw.uf),
  cep: first(raw.cep),
  telefone: first(raw.ddd_telefone_1, raw.telefone),
  email: first(raw.email),
};

return [{
  json: {
    ok: !error,
    cnpj: prepared.cnpj,
    cnpjFormatted: prepared.cnpjFormatted,
    error,
    company,
  },
}];
